namespace sv_ca59fd0ef5a148a6bec82848c2056718.Services;

/// <summary>
/// Scoped service that holds the currently selected warehouse for a single user circuit.
/// Components subscribe to OnChange to react when the warehouse selection changes.
/// </summary>
public class WarehouseState
{
    public string SelectedWarehouseId { get; private set; } = "WH-001";
    public string SelectedWarehouseName { get; private set; } = "Warehouse A";

    public event Action? OnChange;

    public static IReadOnlyList<(string Id, string Name)> AvailableWarehouses { get; } =
    [
        ("WH-001", "Warehouse A"),
        ("WH-002", "Warehouse B"),
        ("WH-003", "Warehouse C"),
        ("WH-004", "Warehouse D"),
    ];

    public void SetWarehouse(string warehouseId)
    {
        var warehouse = AvailableWarehouses.FirstOrDefault(w => w.Id == warehouseId);
        if (warehouse == default) return;

        SelectedWarehouseId = warehouse.Id;
        SelectedWarehouseName = warehouse.Name;
        OnChange?.Invoke();
    }
}

