@implements IDisposable
@inject Services.WarehouseState WarehouseState
@inject Services.InventoryAlertService AlertService

<div class="warehouse-selector">
    <label class="form-label text-white mb-1 small">Current Warehouse</label>
    <select class="form-select form-select-sm" @onchange="OnWarehouseChanged" value="@WarehouseState.SelectedWarehouseId">
        @foreach (var wh in Services.WarehouseState.AvailableWarehouses)
        {
            <option value="@wh.Id">@wh.Name</option>
        }
    </select>
</div>

@code {
    private async Task OnWarehouseChanged(ChangeEventArgs e)
    {
        var newId = e.Value?.ToString();
        if (!string.IsNullOrEmpty(newId))
        {
            WarehouseState.SetWarehouse(newId);
            await AlertService.RefreshAsync();
        }
    }

    private Action? _handler;

    protected override void OnInitialized()
    {
        _handler = () => InvokeAsync(StateHasChanged);
        WarehouseState.OnChange += _handler;
    }

    public void Dispose()
    {
        WarehouseState.OnChange -= _handler;
    }
}

@implements IDisposable
@inject Services.InventoryAlertService AlertService

<span class="badge @BadgeClass">@AlertService.CurrentLowStockCount</span>

@code {
