@page "/dashboard"
@rendermode InteractiveServer
@implements IDisposable
@inject Services.WarehouseState WarehouseState
@inject Services.InventoryAlertService AlertService

<PageTitle>Dashboard - @WarehouseState.SelectedWarehouseName</PageTitle>

<h1>Warehouse Dashboard</h1>
<p class="text-muted">Viewing: <strong>@WarehouseState.SelectedWarehouseName</strong></p>

<div class="row mt-4">
    <div class="col-md-4">
        <div class="card">
            <div class="card-body">
                <h5 class="card-title">Low Stock Alerts</h5>
                <p class="display-4 text-danger">@AlertService.CurrentLowStockCount</p>
                <p class="text-muted">Items below minimum level</p>
                <p class="small text-muted">Auto-refreshes every 10 seconds</p>
            </div>
        </div>
    </div>
    <div class="col-md-4">
        <div class="card">
            <div class="card-body">
                <h5 class="card-title">Alert Badge Component</h5>
                <p>
                    Shared badge:
                    <AlertBadge BadgeClass="bg-warning text-dark" />
                </p>
                <p class="small text-muted">Same data as sidebar — updates together</p>
            </div>
        </div>
    </div>
</div>

@code {
    private Action? _warehouseHandler;
    private Action? _alertHandler;

    protected override void OnInitialized()
    {
        _warehouseHandler = () => InvokeAsync(StateHasChanged);
        _alertHandler = () => InvokeAsync(StateHasChanged);

        WarehouseState.OnChange += _warehouseHandler;
        AlertService.OnAlertDataChanged += _alertHandler;

        AlertService.StartPolling();
    }

    public void Dispose()
    {
        AlertService.StopPolling();
        WarehouseState.OnChange -= _warehouseHandler;
        AlertService.OnAlertDataChanged -= _alertHandler;
    }
}

